insert into public.exercises (id, name, category, description, tips) values
  ('squat', 'Back squat', 'squat', 'Barbell on the upper back, sit down between your hips and stand back up with the bar travelling straight over the middle of the foot.', '{"setup":["Bar on your upper back, hands as close as your shoulders allow.","Walk it out in three steps: back, back, set.","Feet about shoulder width, toes turned out a little."],"execution":["Control the descent.","Keep the bar balanced over your midfoot.","Knees track in the direction of your toes.","Drive up and keep your chest with the bar."],"mistakes":["Knees caving in on the way up.","Hips shooting up first and folding forward.","Diving down fast and bouncing out of the hole."],"bracing":["Big breath into your belly, then brace before descending.","Hold the brace until you are standing again."],"safety":["Use a depth you can control.","Set the safety pins or straps just below your bottom position."]}'::jsonb),
  ('bench-press', 'Bench press', 'bench', 'Lying on the bench with a stable arch and feet on the floor, lower the bar to the chest and press it back up over the shoulders.', '{"setup":["Eyes under the bar, squeeze your shoulder blades together and down.","Feet planted, glutes stay on the bench.","Grip evenly, thumbs around the bar."],"execution":["Lower the bar under control to your lower chest.","Keep your wrists stacked over your elbows.","Press up and slightly back towards your face."],"mistakes":["Bouncing the bar off the chest.","Elbows flaring straight out to the sides.","Butt lifting off the bench."],"bracing":["Breathe in at the top, stay tight through the whole rep.","Maintain a stable setup: upper back pinned to the bench."],"safety":["Use a spotter or safety arms for heavy attempts.","Never use a thumbless grip."]}'::jsonb),
  ('deadlift', 'Deadlift', 'deadlift', 'Pull the barbell from the floor to standing with a neutral spine, keeping the bar close to the legs the whole way.', '{"setup":["Bar over the middle of your foot, shins close to the bar.","Grip just outside your legs, arms straight.","Chest up, hips at a height where your shins touch the bar."],"execution":["Build tension before the bar leaves the floor.","Keep the bar close: drag it up your legs.","Push the floor away, then lock out with your hips.","Lower it under control the same way it came up."],"mistakes":["Jerking the weight from the floor.","Bar drifting away from the shins.","Leaning back excessively at lockout."],"bracing":["Set your brace before pulling.","Re-brace between reps instead of rushing."],"safety":["If your back rounds more than your setup, the weight is too heavy today.","Avoid jerking the weight from the floor."]}'::jsonb),
  ('overhead-press', 'Overhead press', 'accessory', 'Standing barbell press from the front of the shoulders to locked out overhead, with legs and trunk staying still.', '{"setup":["Bar on the front of your shoulders, grip just outside shoulder width.","Feet hip width, squeeze glutes and quads."],"execution":["Move your head back, press the bar in a straight line.","Push your head through once the bar passes your forehead.","Finish with the bar over your midfoot, arms locked."],"mistakes":["Leaning back to turn it into an incline press.","Pressing the bar forward around your face.","Using a knee dip to cheat it up."],"bracing":["Ribs down, abs tight: no banana back."],"safety":["Stop if you feel pinching in the shoulder."]}'::jsonb),
  ('barbell-row', 'Barbell row', 'accessory', 'Hinged over with a flat back, row the barbell from hanging arms to your lower chest or upper belly.', '{"setup":["Hinge at the hips until your torso is close to parallel.","Slight bend in the knees, bar under your shoulders."],"execution":["Pull the bar to your belly, elbows going back.","Squeeze your shoulder blades at the top.","Lower it under control: no dropping."],"mistakes":["Standing up more with every rep.","Yanking the weight with the lower back."],"bracing":["Keep a neutral spine and a tight trunk the whole set."],"safety":["If you cannot keep your back flat, lower the weight."]}'::jsonb),
  ('pull-up', 'Pull-up', 'accessory', 'Hang from a bar with an overhand grip and pull until your chin clears the bar. Bodyweight, or with added weight when Paul says so.', '{"setup":["Hands a bit wider than shoulders, full grip.","Start from a dead hang with straight arms."],"execution":["Pull your elbows down towards your ribs.","Chin over the bar, then lower all the way under control."],"mistakes":["Kipping or swinging for momentum.","Half reps that never reach straight arms."],"bracing":["Squeeze glutes and abs so your legs stay still."],"safety":["Step down instead of dropping from the bar."]}'::jsonb)
